Having `items` point into `witness` makes copy and move operations tricky: it requires a hand-written copy constructor (C.20), and leaves the other special members implicit (C.21). An alternative would be to store offsets. It's a bit more code, but I think it's more idiomatic, and it also halves the memory footprint per item on 64-bit platforms (16 to 8 bytes).

git diff on 4a3067668e

```diff
diff --git a/src/kernel/bitcoinkernel.cpp b/src/kernel/bitcoinkernel.cpp
index 1f6ba57769..d80c37e3db 100644
--- a/src/kernel/bitcoinkernel.cpp
+++ b/src/kernel/bitcoinkernel.cpp
@@ -605,13 +605,36 @@ void KernelLogger::Log(const util::log::Entry& entry) const
     }
 }

-struct WitnessStack {
-    const CScriptWitness witness;
-    const std::vector<std::span<const unsigned char>> items;
+class WitnessStack
+{
+    //! Relative to the first item. CScriptWitness serializations fit in 32 bits.
+    struct ItemPosition {
+        uint32_t offset;
+        uint32_t size;
+    };
+
+    CScriptWitness m_witness;
+    std::vector<ItemPosition> m_positions;

-    explicit WitnessStack(const CScriptWitness& w) : witness{w}, items(witness.begin(), witness.end()) {}
-    // Copied spans would point into other.witness.
-    WitnessStack(const WitnessStack& other) : WitnessStack{other.witness} {}
+public:
+    explicit WitnessStack(const CScriptWitness& witness) : m_witness{witness}
+    {
+        if (m_witness.empty()) return;
+        m_positions.reserve(m_witness.size());
+        const auto* first{m_witness.front().data()};
+        for (const auto item : m_witness) {
+            m_positions.push_back({.offset = static_cast<uint32_t>(item.data() - first),
+                                   .size = static_cast<uint32_t>(item.size())});
+        }
+    }
+
+    size_t Count() const { return m_positions.size(); }
+
+    std::span<const unsigned char> GetItem(size_t index) const
+    {
+        const auto& position{m_positions[index]};
+        return {m_witness.front().data() + position.offset, position.size};
+    }
 };

 } // namespace
